1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { lookupArtistLocation } from "../geo.js";
3	import { classifyPollError } from "../pollError.js";
4	import { fetchCurrentlyPlaying, pause, play, skipToNext } from "../spotify.js";
5	import LeafletMap from "./LeafletMap.jsx";
6	import NowPlayingCard from "./NowPlayingCard.jsx";
7	
8	const POLL_MS = 5_000;
9	const PACIFIC_FALLBACK = { lat: 0, lng: -160, placeName: "Unknown location" };
10	
11	export default function MapView({ token, onTokenExpired }) {
12	  const [track, setTrack] = useState(null);
13	  const [location, setLocation] = useState(null);
14	  const [status, setStatus] = useState("loading");
15	  const [controlMessage, setControlMessage] = useState(null);
16	  const lastArtistRef = useRef(null);
17	  const refreshingRef = useRef(false);
18	  const mountedRef = useRef(true);
19	
20	  useEffect(() => {
21	    mountedRef.current = true;
22	    return () => {
23	      mountedRef.current = false;
24	    };
25	  }, []);
26	
27	  // Fetch the currently-playing track and update state. Throws on API error so
28	  // callers (the poll loop and the control handlers) can apply their own
29	  // error handling. Both share this so a control action can refresh instantly.
30	  const syncNowPlaying = useCallback(async () => {
31	    const current = await fetchCurrentlyPlaying(token);
32	    if (!mountedRef.current) return;
33	
34	    if (!current) {
35	      if (import.meta.env.DEV) console.info("[poll] nothing playing");
36	      setStatus("idle");
37	      return;
38	    }
39	
40	    // update track immediately; location catches up asynchronously
41	    setTrack(current);
42	    setStatus("playing");
43	    if (import.meta.env.DEV) {
44	      console.info(
45	        `[poll] now playing: ${current.artistName} – ${current.trackName}`,
46	      );
47	    }
48	
49	    if (current.artistName !== lastArtistRef.current) {
50	      lastArtistRef.current = current.artistName;
51	      if (import.meta.env.DEV) {
52	        console.info(`[poll] artist changed, looking up ${current.artistName}`);
53	      }
54	      const loc = await lookupArtistLocation(current.artistName);
55	      if (mountedRef.current) setLocation(loc ?? PACIFIC_FALLBACK);
56	    }
57	  }, [token]);
58	
59	  // Shared TOKEN_EXPIRED refresh path, guarded so only one refresh runs at a
60	  // time even across overlapping poll/control errors.
61	  const refreshToken = useCallback(async () => {
62	    if (refreshingRef.current) return;
63	    refreshingRef.current = true;
64	    if (import.meta.env.DEV) console.info("[poll] token expired, refreshing");
65	    try {
66	      await onTokenExpired();
67	    } finally {
68	      refreshingRef.current = false;
69	    }
70	  }, [onTokenExpired]);
71	
72	  useEffect(() => {
73	    let cancelled = false;
74	
75	    async function poll() {
76	      if (cancelled) return;
77	      try {
78	        await syncNowPlaying();
79	      } catch (err) {
80	        if (cancelled) return;
81	        const action = classifyPollError(err.message);
82	        if (action.type === "refresh") {
83	          await refreshToken();
84	          return;
85	        }
86	        if (action.type === "retry") {
87	          if (import.meta.env.DEV) {
88	            console.info(`[poll] rate limited, retrying in ${action.seconds}s`);
89	          }
90	          // safe to schedule even near unmount: poll() checks cancelled at the top
91	          setTimeout(poll, action.seconds * 1000);
92	          return;
93	        }
94	        console.error("[poll] error:", err.message);
95	        setStatus("error");
96	      }
97	    }
98	
99	    poll();
100	    const id = setInterval(poll, POLL_MS);
101	    return () => {
102	      cancelled = true;
103	      clearInterval(id);
104	    };
105	  }, [syncNowPlaying, refreshToken]);
106	
107	  async function runControl(action) {
108	    try {
109	      await action();
110	      setControlMessage(null);
111	      return true;
112	    } catch (err) {
113	      if (err.message === "TOKEN_EXPIRED") {
114	        await refreshToken();
115	      } else {
116	        setControlMessage("Playback control not available");
117	      }
118	      return false;
119	    }
120	  }
121	
122	  async function handlePlayPause() {
123	    const wasPlaying = track?.isPlaying;
124	    const ok = await runControl(() =>
125	      wasPlaying ? pause(token) : play(token),
126	    );
127	    if (!ok) return;
128	    // optimistic flip so the icon updates before the next poll lands
129	    setTrack((t) => (t ? { ...t, isPlaying: !wasPlaying } : t));
130	    syncNowPlaying().catch(() => {});
131	  }
132	
133	  async function handleNext() {
134	    const ok = await runControl(() => skipToNext(token));
135	    if (!ok) return;
136	    syncNowPlaying().catch(() => {});
137	  }
