88	    await vi.advanceTimersByTimeAsync(0); // initial poll -> refresh in flight (pending)
89	    await vi.advanceTimersByTimeAsync(5000); // interval fires a 2nd poll while pending
90	    expect(onTokenExpired).toHaveBeenCalledTimes(1);
