105	    fetchCurrentlyPlaying.mockResolvedValue(PLAYING_TRACK);
106	    render(<MapView token="t" onTokenExpired={vi.fn()} />);
107	    await waitFor(() =>
108	      expect(screen.getByTestId("now-playing-card")).toBeInTheDocument(),
109	    );
110	  });
111	
