113	    fetchCurrentlyPlaying.mockResolvedValue(PLAYING_TRACK);
114	    render(<MapView token="t" onTokenExpired={vi.fn()} />);
115	    await waitFor(() =>
116	      expect(screen.getByTestId("now-playing-card")).toBeInTheDocument(),
117	    );
