125	    render(<MapView token="t" onTokenExpired={vi.fn()} />);
126	    await waitFor(() =>
127	      expect(screen.getByTestId("now-playing-card")).toBeInTheDocument(),
128	    );
129	    fireEvent.click(screen.getByText("next"));
130	    await waitFor(() => expect(skipToNext).toHaveBeenCalledWith("t"));
131	  });
132	
133	  it("shows a control message when playback control fails", async () => {
134	    fetchCurrentlyPlaying.mockResolvedValue(PLAYING_TRACK);
135	    pause.mockRejectedValueOnce(new Error("PLAYBACK_UNAVAILABLE"));
136	    render(<MapView token="t" onTokenExpired={vi.fn()} />);
137	    await waitFor(() =>
138	      expect(screen.getByTestId("now-playing-card")).toBeInTheDocument(),
