    it("does not start the interval when paused", () => {
      render(
        <NowPlayingCard
          track={makeTrack({ isPlaying: false })}
          placeName="X"
          onPlayPause={vi.fn()}
          onNext={vi.fn()}
          controlMessage={null}
        />,
      );
      vi.advanceTimersByTime(1500);
      expect(screen.getByTestId("progress-fill")).toBeInTheDocument();
    });
  });
});

